DROP TABLE IF EXISTS database_sistem_ekonomi;
CREATE TABLE database_sistem_ekonomi (
id SERIAL NOT NULL PRIMARY KEY,
country_id INT NOT NULL,
country_slug VARCHAR(100) NOT NULL,
country_name VARCHAR(100) NOT NULL,
iso VARCHAR(10) NOT NULL,
spektrum_val INT NOT NULL DEFAULT 50, -- 0 (Terpusat/Komando) - 100 (Pasar Bebas/Laissez-Faire)
system_title VARCHAR(100) NOT NULL,
category VARCHAR(255) NOT NULL,
policy_price_control VARCHAR(255) NOT NULL DEFAULT 'Terpusat',
policy_strategic_ownership VARCHAR(255) NOT NULL DEFAULT 'Terpusat',
policy_trade VARCHAR(255) NOT NULL DEFAULT 'Pasar Bebas',
policy_labor VARCHAR(255) NOT NULL DEFAULT 'Pasar Bebas'
);
-- ========================================================
